CREATE TABLE lottery_draws (id INTEGER PRIMARY KEY AUTOINCREMENT, draw_id TEXT NOT NULL UNIQUE, draw_number INTEGER NOT NULL UNIQUE, draw_date TEXT NOT NULL, n1 INTEGER NOT NULL, n2 INTEGER NOT NULL, n3 INTEGER NOT NULL, n4 INTEGER NOT NULL, n5 INTEGER NOT NULL, n6 INTEGER NOT NULL, bonus_number INTEGER NOT NULL, source TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), CHECK(n1>=1 AND n6<=43), CHECK(n1<n2 AND n2<n3 AND n3<n4 AND n4<n5 AND n5<n6), CHECK(bonus_number BETWEEN 1 AND 43));
CREATE TABLE prediction_matches (id INTEGER PRIMARY KEY AUTOINCREMENT, prediction_id TEXT NOT NULL REFERENCES predictions(prediction_id), draw_id TEXT NOT NULL REFERENCES lottery_draws(draw_id), tracking_type TEXT NOT NULL CHECK(tracking_type IN ('historical_backtest','forward_tracking')), main_match_count INTEGER NOT NULL CHECK(main_match_count BETWEEN 0 AND 6), bonus_match INTEGER NOT NULL CHECK(bonus_match IN (0,1)), equivalent_rank TEXT CHECK(equivalent_rank IN ('1','2','3','4','5') OR equivalent_rank IS NULL), elapsed_days INTEGER, elapsed_draws INTEGER, checked_at TEXT NOT NULL, UNIQUE(prediction_id,draw_id));
CREATE INDEX idx_prediction_matches_prediction ON prediction_matches(prediction_id,tracking_type);
CREATE INDEX idx_prediction_matches_draw ON prediction_matches(draw_id);
CREATE TABLE prediction_tracking_summary (prediction_id TEXT PRIMARY KEY REFERENCES predictions(prediction_id), checked_draw_count INTEGER NOT NULL DEFAULT 0, best_main_match_count INTEGER NOT NULL DEFAULT 0, best_bonus_match INTEGER NOT NULL DEFAULT 0, best_equivalent_rank TEXT, best_draw_id TEXT REFERENCES lottery_draws(draw_id), days_to_best INTEGER, draws_to_best INTEGER, first_3plus_draw_id TEXT REFERENCES lottery_draws(draw_id), updated_at TEXT NOT NULL);
CREATE TABLE prediction_generation_features (prediction_id TEXT PRIMARY KEY REFERENCES predictions(prediction_id), features_json TEXT NOT NULL, captured_at TEXT NOT NULL);
CREATE TRIGGER trg_lottery_draws_no_update BEFORE UPDATE ON lottery_draws BEGIN SELECT RAISE(ABORT,'lottery_draws are immutable'); END;
CREATE TRIGGER trg_lottery_draws_no_delete BEFORE DELETE ON lottery_draws BEGIN SELECT RAISE(ABORT,'lottery_draws are immutable'); END;
CREATE TRIGGER trg_prediction_matches_no_update BEFORE UPDATE ON prediction_matches BEGIN SELECT RAISE(ABORT,'prediction_matches are immutable'); END;
CREATE TRIGGER trg_prediction_matches_no_delete BEFORE DELETE ON prediction_matches BEGIN SELECT RAISE(ABORT,'prediction_matches are immutable'); END;
